(6850, 'Bộ dụng cụ cơ bản Bandai Spirits Entry Tool Set', 'bandai-spirits-entry-tool-set', 220000, 50, 90, NULL, NULL, NULL, 'Bộ công cụ nhập môn chính hãng Bandai gồm kềm cơ bản và nhíp, dành cho người mới bắt đầu.', 'images/tools/bandai-entry-set.jpg', 250, 1, '2026-05-14 10:49:16'),
(6851, 'Kềm cắt Plato 170', 'kem-cat-plato-170', 45000, 200, 41, NULL, NULL, NULL, 'Kềm Plato giá rẻ, thích hợp cho người mới tập chơi dùng để cắt runner hoặc cắt dây kẽm mỏng.', 'images/tools/plato-170.jpg', 60, 1, '2026-05-14 10:49:16'),
(6852, 'Kềm Mineshima D-25 Premium Nipper', 'mineshima-d25-premium-nipper', 350000, 40, 41, NULL, NULL, NULL, 'Kềm lưỡi mỏng Mineshima sản xuất tại Nhật Bản, độ bền cao, cho vết cắt ngọt và đẹp.', 'images/tools/mineshima-d25.jpg', 100, 1, '2026-05-14 10:49:16'),
(6853, 'Dao trổ chuyên dụng OLFA AK-4', 'olfa-ak-4-art-knife', 280000, 30, 42, NULL, NULL, NULL, 'Dao trổ cao cấp OLFA AK-4 kèm các lưỡi dao đa năng dự phòng, tay cầm bọc cao su chống mỏi tay khi gọt ghẻ lâu.', 'images/tools/olfa-ak4.jpg', 80, 1, '2026-05-14 10:49:16'),
(6854, 'Bộ giấy nhám xốp DSPIAE (Siren)', 'dspiae-siren-sponge-sandpaper', 150000, 80, 44, NULL, NULL, NULL, 'Giấy nhám xốp DSPIAE có đánh số độ mịn rõ ràng từ #400 đến #1500, chống gập gãy, dễ dàng chà các bề mặt cong.', 'images/tools/dspiae-sponge.jpg', 50, 1, '2026-05-14 10:49:16'),
(6855, 'Bộ 3 dũa kim loại Tamiya Basic File Set', 'tamiya-basic-file-set-104', 180000, 45, 44, NULL, NULL, NULL, 'Bộ 3 dũa kim loại Tamiya (Bản dẹt, bán nguyệt, tròn) chuyên dùng để xử lý nhanh các vết cắt gờ nhựa cao.', 'images/tools/tamiya-basic-file.jpg', 120, 1, '2026-05-14 10:49:16'),
(6856, 'Tamiya Panel Line Accent Color (Gray)', 'tamiya-panel-line-accent-gray', 120000, 100, 51, NULL, NULL, NULL, 'Dung dịch kẻ lằn chìm màu xám (Gray), cực kỳ phù hợp cho các part giáp màu trắng để tạo hiệu ứng tự nhiên, không bị quá gắt như màu đen.', 'images/tools/tamiya-panel-gray.jpg', 100, 1, '2026-05-14 10:49:16'),
(6857, 'Bút kẻ chảy tự động Gundam Marker GM301 (Black)', 'gundam-marker-gm301-pour-type', 75000, 150, 51, NULL, NULL, NULL, 'Bút kẻ lằn chìm dạng chảy tự động (Pour type), chỉ cần chấm nhẹ đầu bút vào rãnh, mực sẽ tự loang theo đường rãnh.', 'images/tools/marker-gm301.jpg', 30, 1, '2026-05-14 10:49:16'),
(6858, 'Keo dán hỗ trợ Decal Mr. Mark Setter', 'mr-mark-setter', 90000, 70, 53, NULL, NULL, NULL, 'Dung dịch tăng độ bám dính cực mạnh cho decal nước, giúp decal bám chắc vào bề mặt nhựa nhám, chống tróc theo thời gian.', 'images/tools/mr-mark-setter.jpg', 80, 1, '2026-05-14 10:49:16'),
(6859, 'Sơn phủ Mr. Premium Topcoat Flat (Gốc nước)', 'mr-premium-topcoat-flat', 220000, 50, 61, NULL, NULL, NULL, 'Sơn phủ dạng xịt gốc nước Premium. Ưu điểm tuyệt đối là không làm chảy mực panel line hay ăn mòn hỏng decal, tạo hiệu ứng nhám mịn cực đẹp.', 'images/tools/mr-premium-flat.jpg', 250, 1, '2026-05-14 10:49:16'),
(6860, 'Keo dán Tamiya Cement (Nắp trắng)', 'tamiya-cement-white', 110000, 80, 62, NULL, NULL, NULL, 'Keo dán mô hình dạng đặc, độ kết dính cực mạnh, thời gian khô chậm, lý tưởng để ghép chặt các part lớn lại với nhau.', 'images/tools/tamiya-cement-white.jpg', 120, 1, '2026-05-14 10:49:16'),
(6861, 'Mũi khắc rãnh BMC Chisel 0.2mm', 'bmc-chisel-02mm', 850000, 10, 71, NULL, NULL, NULL, 'Mũi khắc lằn chìm (Scriber) huyền thoại BMC cỡ 0.2mm làm từ thép Tungsten, mang lại độ sắc bén và chính xác tuyệt đối cho modder.', 'images/tools/bmc-02.jpg', 50, 1, '2026-05-14 10:49:16'),
(6862, 'Action Base 1 (Black)', 'action-base-1-black', 160000, 120, 82, NULL, NULL, NULL, 'Giá đỡ Action Base 1 cỡ lớn chính hãng Bandai, thiết kế cực kỳ vững chắc, chuyên dụng cho mô hình MG (1/100) và các mẫu có trọng lượng nặng.', 'images/tools/action-base-1-black.jpg', 250, 1, '2026-05-14 10:49:16'),
(6863, 'Action Base 5 (Black)', 'action-base-5-black', 150000, 150, 82, NULL, NULL, NULL, 'Giá đỡ Action Base 5, thiết kế hiện đại, tinh gọn, rất phù hợp cho HG/RG (1/144), có khớp nối để ghép nhiều base tạo đội hình.', 'images/tools/action-base-5-black.jpg', 180, 1, '2026-05-14 10:49:16'),
(6864, 'Khay nam châm phân loại part DSPIAE', 'dspiae-magnetic-parts-tray', 250000, 40, 83, NULL, NULL, NULL, 'Khay nhôm cao cấp đựng linh kiện tích hợp nam châm của hãng DSPIAE, chống thất lạc các part nhựa siêu nhỏ hoặc chi tiết kim loại.', 'images/tools/dspiae-tray.jpg', 300, 1, '2026-05-14 10:49:16'),
(6865, 'Kềm cắt DSPIAE ST-A 3.0 Single-blade', 'dspiae-st-a-30-nipper', 750000, 30, 41, NULL, NULL, NULL, 'Kềm cắt lưỡi đơn thế hệ 3.0 của DSPIAE, thép rèn nhiệt luyện siêu bén, đối thủ xứng tầm của Godhand SPN-120.', 'images/tools/dspiae-sta.jpg', 120, 1, '2026-05-14 10:49:16'),
(6866, 'Kềm Tamiya 74093 Modeler\'s Side Cutter', 'tamiya-74093-modeler-cutter', 650000, 40, 41, NULL, NULL, NULL, 'Kềm cắt tiêu chuẩn của Tamiya, lưỡi sắc bén, độ bền cao dành cho người chơi lâu dài.', 'images/tools/tamiya-74093.jpg', 150, 1, '2026-05-14 10:49:16'),
(6867, 'Kềm cắt Bandai Build Up Nipper', 'bandai-build-up-nipper', 250000, 100, 41, NULL, NULL, NULL, 'Kềm chính hãng Bandai dành cho người mới, cắt nhựa êm, an toàn và dễ sử dụng.', 'images/tools/bandai-build-nipper.jpg', 100, 1, '2026-05-14 10:49:16'),
(6868, 'Kềm Mineshima D-29a', 'mineshima-d29a-nipper', 180000, 50, 41, NULL, NULL, NULL, 'Kềm nội địa Nhật Bản giá rẻ, lưỡi cắt thiết kế riêng cho việc tách mảnh nhựa khỏi runner.', 'images/tools/mineshima-d29a.jpg', 110, 1, '2026-05-14 10:49:16'),
(6869, 'Dao trổ Tamiya 74040 Modeler\'s Knife', 'tamiya-74040-modeler-knife', 220000, 80, 42, NULL, NULL, NULL, 'Dao trổ đầu nhọn 30 độ huyền thoại của Tamiya, đi kèm hộp lưỡi dao thay thế.', 'images/tools/tamiya-74040.jpg', 60, 1, '2026-05-14 10:49:16'),
(6870, 'Dao trổ cán nhôm DSPIAE AT-TH', 'dspiae-at-th-aluminum-knife', 180000, 60, 42, NULL, NULL, NULL, 'Dao trổ cán nhôm nguyên khối DSPIAE, trọng tâm dồn về mũi dao giúp cắt ghẻ nhựa không tốn sức.', 'images/tools/dspiae-atth.jpg', 80, 1, '2026-05-14 10:49:16'),
(6871, 'Dao trổ OLFA 11B Art Knife', 'olfa-11b-art-knife', 150000, 100, 42, NULL, NULL, NULL, 'Dao cắt mỹ thuật OLFA (hãng sản xuất dao cho Tamiya), độ bén tuyệt hảo.', 'images/tools/olfa-11b.jpg', 50, 1, '2026-05-14 10:49:16'),
(6872, 'Nhíp thẳng Tamiya 74047 Straight Tweezers', 'tamiya-74047-straight-tweezers', 250000, 40, 43, NULL, NULL, NULL, 'Nhíp mũi thẳng Tamiya, chuyên dụng gắp các chi tiết nhựa nhỏ hoặc lò xo.', 'images/tools/tamiya-74047.jpg', 30, 1, '2026-05-14 10:49:16'),
(6873, 'Nhíp chống tĩnh điện DSPIAE AT-TZ', 'dspiae-at-tz-tweezers', 120000, 60, 43, NULL, NULL, NULL, 'Nhíp thép không gỉ DSPIAE sơn tĩnh điện, gắp decal không bị dính ngược vào nhíp.', 'images/tools/dspiae-attz.jpg', 30, 1, '2026-05-14 10:49:16'),
(6874, 'Nhíp thép không gỉ Vetus ST-11', 'vetus-st-11-tweezers', 50000, 150, 43, NULL, NULL, NULL, 'Nhíp Vetus giá rẻ mỏ nhọn siêu mảnh, dùng để gắp part hoặc nhúng decal nước.', 'images/tools/vetus-st11.jpg', 25, 1, '2026-05-14 10:49:16'),
(6875, 'Nhám xốp Tamiya Sanding Sponge 400', 'tamiya-sponge-400', 90000, 100, 44, NULL, NULL, NULL, 'Nhám xốp Tamiya độ nhám 400, chuyên phá ghẻ nhựa thô cứng.', 'images/tools/tamiya-sponge-400.jpg', 20, 1, '2026-05-14 10:49:16'),
(6876, 'Nhám xốp Tamiya Sanding Sponge 600', 'tamiya-sponge-600', 90000, 100, 44, NULL, NULL, NULL, 'Nhám xốp Tamiya độ nhám 600, bước thứ hai trong quy trình chà nhám Gunpla.', 'images/tools/tamiya-sponge-600.jpg', 20, 1, '2026-05-14 10:49:16'),
(6877, 'Nhám xốp Tamiya Sanding Sponge 1000', 'tamiya-sponge-1000', 90000, 100, 44, NULL, NULL, NULL, 'Nhám xốp Tamiya độ nhám 1000, làm mịn bề mặt trước khi phủ sơn hoặc topcoat.', 'images/tools/tamiya-sponge-1000.jpg', 20, 1, '2026-05-14 10:49:16'),
(6878, 'Nhám xốp Tamiya Sanding Sponge 1500', 'tamiya-sponge-1500', 90000, 100, 44, NULL, NULL, NULL, 'Nhám xốp Tamiya độ nhám 1500, dùng để đánh bóng nhẹ bề mặt nhựa.', 'images/tools/tamiya-sponge-1500.jpg', 20, 1, '2026-05-14 10:49:16'),
(6879, 'Thanh chà bóng Gunprimer Balancer White', 'gunprimer-balancer-white', 160000, 40, 44, NULL, NULL, NULL, 'Thanh nhám bọt biển cao cấp Gunprimer (Trắng), phục hồi độ bóng nguyên bản của nhựa.', 'images/tools/gunprimer-white.jpg', 30, 1, '2026-05-14 10:49:16'),
(6880, 'Thanh mài mờ Gunprimer Balancer Gray', 'gunprimer-balancer-gray', 160000, 40, 44, NULL, NULL, NULL, 'Thanh nhám Gunprimer (Xám), tạo hiệu ứng bề mặt nhám mờ đẹp mắt ngay lập tức.', 'images/tools/gunprimer-gray.jpg', 30, 1, '2026-05-14 10:49:16'),
(6881, 'Thanh dũa nam châm DSPIAE MS-01', 'dspiae-ms-01-magnetic-sander', 200000, 50, 44, NULL, NULL, NULL, 'Thanh dũa hợp kim nhôm dán giấy nhám bằng lực hút nam châm, luôn đảm bảo bề mặt chà phẳng tuyệt đối.', 'images/tools/dspiae-ms01.jpg', 90, 1, '2026-05-14 10:49:16'),
(6882, 'Giấy nhám xốp GodHand Kamiyasu 2mm Assortment', 'godhand-kamiyasu-2mm', 150000, 60, 44, NULL, NULL, NULL, 'Set nhám xốp GodHand siêu bền độ dày 2mm (đủ số 400/600/800/1000), chuyên uốn lượn bề mặt cong.', 'images/tools/godhand-kami-2mm.jpg', 40, 1, '2026-05-14 10:49:16'),
(6883, 'Giấy nhám xốp GodHand Kamiyasu 5mm Assortment', 'godhand-kamiyasu-5mm', 150000, 60, 44, NULL, NULL, NULL, 'Set nhám xốp GodHand độ dày 5mm, cầm chắc tay, lực chà đều.', 'images/tools/godhand-kami-5mm.jpg', 50, 1, '2026-05-14 10:49:16'),
(6884, 'Thanh dũa Infini Model Zebra', 'infini-model-zebra-stick', 65000, 120, 44, NULL, NULL, NULL, 'Thanh dũa xốp 2 mặt cứng cáp Infini Model, tiện dụng cho việc mài phẳng góc cạnh.', 'images/tools/infini-zebra.jpg', 20, 1, '2026-05-14 10:49:16'),
(6885, 'Tamiya Panel Line Accent Color (Brown)', 'tamiya-panel-line-brown', 120000, 100, 51, NULL, NULL, NULL, 'Dung dịch kẻ lằn chìm màu Nâu, dùng cho các giáp màu vàng, đỏ hoặc cam.', 'images/tools/tamiya-panel-brown.jpg', 100, 1, '2026-05-14 10:49:16'),
(6886, 'Tamiya Panel Line Accent Color (Dark Gray)', 'tamiya-panel-line-dark-gray', 120000, 100, 51, NULL, NULL, NULL, 'Dung dịch kẻ lằn chìm màu Xám Đậm, thay thế màu đen để đường kẻ bớt gắt trên giáp trắng.', 'images/tools/tamiya-panel-darkgray.jpg', 100, 1, '2026-05-14 10:49:16'),
(6887, 'Gundam Marker GM02 (Gray Fine)', 'gundam-marker-gm02-gray', 65000, 150, 51, NULL, NULL, NULL, 'Bút kẻ viền ngòi kim màu xám GM02, mực ra đều, dễ dùng cho newbie.', 'images/tools/marker-gm02.jpg', 30, 1, '2026-05-14 10:49:16'),
(6888, 'Gundam Marker GM03 (Brown Fine)', 'gundam-marker-gm03-brown', 65000, 150, 51, NULL, NULL, NULL, 'Bút kẻ viền ngòi kim màu nâu GM03.', 'images/tools/marker-gm03.jpg', 30, 1, '2026-05-14 10:49:16'),
(6889, 'Gundam Marker GM302 (Gray Pour Type)', 'gundam-marker-gm302-gray-pour', 75000, 150, 51, NULL, NULL, NULL, 'Bút kẻ lằn chảy GM302 màu Xám, mực tự động loang theo rãnh nhựa.', 'images/tools/marker-gm302.jpg', 30, 1, '2026-05-14 10:49:16'),
