(6893, 'Gundam Marker EX Cosmo M Blue (XGM04)', 'marker-ex-cosmo-blue', 85000, 60, 52, NULL, NULL, NULL, 'Bút sơn Marker EX màu xanh biển ánh kim Metallic.', 'images/tools/marker-xgm04.jpg', 30, 1, '2026-05-14 10:49:16'),
