(6897, 'Dung dịch dán decal Tamiya Mark Fit', 'tamiya-mark-fit-standard', 85000, 100, 53, NULL, NULL, NULL, 'Dung dịch Tamiya Mark Fit tiêu chuẩn, làm mềm và tăng độ bám cho decal nước.', 'images/tools/tamiya-mark-fit.jpg', 70, 1, '2026-05-14 10:49:16'),
(6898, 'Dung dịch dán decal Tamiya Mark Fit (Strong)', 'tamiya-mark-fit-strong', 95000, 80, 53, NULL, NULL, NULL, 'Dung dịch Mark Fit nắp vàng (Strong), dùng cho decal dày cứng đầu bám vào bề mặt cong/gồ ghề.', 'images/tools/tamiya-mark-fit-strong.jpg', 70, 1, '2026-05-14 10:49:16'),
(6899, 'Khay ngâm decal nước DSPIAE', 'dspiae-decal-tray', 180000, 40, 53, NULL, NULL, NULL, 'Khay ngâm decal chuyên dụng DSPIAE tích hợp đệm bọt biển giữ ẩm lâu.', 'images/tools/dspiae-decal-tray.jpg', 150, 1, '2026-05-14 10:49:16'),
(6900, 'Dụng cụ tách mảnh DSPIAE PT-MPS', 'dspiae-pt-mps-separator', 150000, 60, 54, NULL, NULL, NULL, 'Nạy tách mảnh nhựa DSPIAE làm bằng thép không gỉ siêu mỏng, không làm xước cạnh nhựa.', 'images/tools/dspiae-ptmps.jpg', 50, 1, '2026-05-14 10:49:16'),
