(6902, 'Sơn phủ Mr. Super Clear Semi-Gloss (B514)', 'mr-super-clear-semi-gloss', 190000, 50, 61, NULL, NULL, NULL, 'Chai xịt Topcoat tạo độ bóng mờ (Semi-Gloss) gốc dung môi, giữ nguyên độ bóng gốc của nhựa Bandai.', 'images/tools/mr-super-clear-semi.jpg', 250, 1, '2026-05-14 10:49:16'),
(6903, 'Sơn phủ Mr. Premium Topcoat Gloss (B501)', 'mr-premium-topcoat-gloss', 220000, 50, 61, NULL, NULL, NULL, 'Chai xịt Topcoat Gloss gốc nước Premium, an toàn tuyệt đối với mọi loại sơn và decal bên dưới.', 'images/tools/mr-premium-gloss.jpg', 250, 1, '2026-05-14 10:49:16'),
